import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Resource 与 Dependency 模型","description":"","frontmatter":{"title":"Resource 与 Dependency 模型"},"headers":[],"relativePath":"zh/guide/resources.md","filePath":"zh/guide/resources.md","lastUpdated":0}`),a={name:`zh/guide/resources.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_3-resource-与-dependency-模型" tabindex="-1">3. Resource 与 Dependency 模型 <a class="header-anchor" href="#_3-resource-与-dependency-模型" aria-label="Permalink to “3. Resource 与 Dependency 模型”">​</a></h1><h2 id="_3-1-resource-定义" tabindex="-1">3.1 Resource 定义 <a class="header-anchor" href="#_3-1-resource-定义" aria-label="Permalink to “3.1 Resource 定义”">​</a></h2><p>Resource 是 Custos 监控和恢复的基本对象。</p><p>资源类型示例：</p><ul><li><code>process</code></li><li><code>system-service</code></li><li><code>network-interface</code></li><li><code>network-connectivity</code></li><li><code>proxy</code></li><li><code>tunnel</code></li><li><code>http-endpoint</code></li><li><code>custom-command</code></li><li><code>database</code></li><li><code>application</code></li></ul><p>每个资源应具有：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Resource</span></span>
<span class="line"><span>├── id</span></span>
<span class="line"><span>├── type</span></span>
<span class="line"><span>├── display_name</span></span>
<span class="line"><span>├── plugin_ref</span></span>
<span class="line"><span>├── config</span></span>
<span class="line"><span>├── health_policy</span></span>
<span class="line"><span>├── recovery_policy</span></span>
<span class="line"><span>├── dependencies[]</span></span>
<span class="line"><span>├── permissions</span></span>
<span class="line"><span>└── enabled</span></span></code></pre></div><p>字段语义：</p><ul><li><code>id</code>：配置范围内稳定且唯一的标识。</li><li><code>type</code>：资源类型。</li><li><code>plugin_ref</code>：实现资源能力的插件。</li><li><code>config</code>：资源类型专属配置。</li><li><code>health_policy</code>：健康判定、连续失败阈值和恢复确认要求。</li><li><code>recovery_policy</code>：恢复候选方案和恢复限制。</li><li><code>dependencies</code>：资源的前置依赖。</li><li><code>permissions</code>：该资源允许的操作范围。</li><li><code>enabled</code>：是否启用监控和自动恢复。</li></ul><p>资源 ID 不应因进程重启、插件重启或机器重启而变化。</p><h2 id="_3-2-resource-健康状态" tabindex="-1">3.2 Resource 健康状态 <a class="header-anchor" href="#_3-2-resource-健康状态" aria-label="Permalink to “3.2 Resource 健康状态”">​</a></h2><p>建议使用以下健康状态：</p><div class="language-rust" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">enum</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HealthStatus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Healthy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Degraded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Unhealthy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Recovering</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Suppressed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Unreachable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>状态语义：</p><ul><li><code>Unknown</code>：尚未获得足够证据。</li><li><code>Healthy</code>：满足健康条件。</li><li><code>Degraded</code>：部分能力异常，但仍能提供服务。</li><li><code>Unhealthy</code>：明确不满足健康条件。</li><li><code>Recovering</code>：正在执行恢复流程。</li><li><code>Suppressed</code>：依据策略暂停自动处理。</li><li><code>Unreachable</code>：探测手段本身无法取得有效结果，尚不能确认根因。</li></ul><p><code>Unreachable</code> 不能直接等同于 <code>Unhealthy</code>。例如，探测远端服务超时，可能是远端故障，也可能是本机网络故障。</p><p>资源状态还应记录：</p><ul><li>状态更新时间。</li><li>连续成功与失败次数。</li><li>最近一次有效探测时间。</li><li>当前生效的故障标识。</li><li>正在执行的 RecoveryRun。</li><li>当前证据摘要。</li></ul><h2 id="_3-3-dependency-定义" tabindex="-1">3.3 Dependency 定义 <a class="header-anchor" href="#_3-3-dependency-定义" aria-label="Permalink to “3.3 Dependency 定义”">​</a></h2><p>依赖关系描述资源正常运行所需要满足的条件。</p><p>建议定义：</p><div class="language-rust" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    target_resource_id</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ResourceId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    requirement</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DependencyRequirement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    condition</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HealthCondition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resolution_policy</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DependencyResolutionPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    timeout</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Duration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>其中：</p><div class="language-rust" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">enum</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DependencyRequirement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Optional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Conditional</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    AlternativeGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>具体语义：</p><h3 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to “Required”">​</a></h3><p>必须满足的依赖。</p><p>如果不满足，则不能执行依赖该条件的恢复动作，除非该动作被明确标记为用于恢复该依赖本身。</p><h3 id="optional" tabindex="-1">Optional <a class="header-anchor" href="#optional" aria-label="Permalink to “Optional”">​</a></h3><p>非强制依赖。</p><p>可以尝试恢复，但是否阻塞上层操作由策略决定。</p><h3 id="conditional" tabindex="-1">Conditional <a class="header-anchor" href="#conditional" aria-label="Permalink to “Conditional”">​</a></h3><p>仅在特定条件下需要满足。</p><p>例如，使用代理模式时需要代理健康；直连模式下则不需要。</p><h3 id="alternativegroup" tabindex="-1">AlternativeGroup <a class="header-anchor" href="#alternativegroup" aria-label="Permalink to “AlternativeGroup”">​</a></h3><p>多个候选资源中满足指定数量即可。</p><p>例如：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ProxyAccess</span></span>
<span class="line"><span>├── PrimaryProxy</span></span>
<span class="line"><span>└── BackupProxy</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：至少一个可用</span></span></code></pre></div><p>不能把备用资源简单地建模成所有依赖都必须正常。</p><h2 id="_3-4-健康条件" tabindex="-1">3.4 健康条件 <a class="header-anchor" href="#_3-4-健康条件" aria-label="Permalink to “3.4 健康条件”">​</a></h2><p>依赖必须声明依赖的是哪种健康条件，而不是只声明依赖某个资源。</p><p>示例：</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">resource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">proxy.egress</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    requirement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">required</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">healthy</span></span></code></pre></div><p>更复杂的条件可以要求：</p><ul><li>资源状态为 Healthy。</li><li>特定能力可用。</li><li>最近一次成功探测不超过指定时间。</li><li>连续成功达到指定次数。</li><li>特定业务检查通过。</li></ul><p>第一版应只实现少量明确、可测试的条件，不要设计任意表达式语言。</p><h2 id="_3-5-依赖图和循环检测" tabindex="-1">3.5 依赖图和循环检测 <a class="header-anchor" href="#_3-5-依赖图和循环检测" aria-label="Permalink to “3.5 依赖图和循环检测”">​</a></h2><p>依赖关系构成有向图。</p><p>如果资源 A 依赖 B，则依赖边为：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A -&gt; B</span></span></code></pre></div><p>恢复 A 时，先评估 B。</p><p>配置加载时必须：</p><ol><li>验证资源 ID 唯一。</li><li>验证所有依赖引用存在。</li><li>检测硬依赖循环。</li><li>验证 AlternativeGroup 的配置合法。</li><li>检查是否存在不可能满足的依赖条件。</li><li>输出具体的配置错误路径。</li></ol><p>对于：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A -&gt; B -&gt; C -&gt; A</span></span></code></pre></div><p>必须在配置阶段拒绝启动，不能等到恢复时才无限递归。</p><p>第一版可以禁止所有普通依赖环；未来如果需要循环或互为备份关系，应通过显式的冗余组建模，而不是允许任意循环。</p><h2 id="_3-6-依赖恢复算法" tabindex="-1">3.6 依赖恢复算法 <a class="header-anchor" href="#_3-6-依赖恢复算法" aria-label="Permalink to “3.6 依赖恢复算法”">​</a></h2><p>恢复资源 A 时：</p><ol><li>获取 A 的依赖集合。</li><li>检查每个依赖的当前状态是否足够新。</li><li>状态未知或已过期时重新探测。</li><li>满足条件的依赖直接通过。</li><li>未满足的依赖按照自身策略进入恢复流程。</li><li>等待依赖恢复完成。</li><li>重新验证依赖健康状态。</li><li>全部必需依赖满足后，才允许执行 A 的恢复动作。</li><li>如果依赖恢复失败，则根据 A 的策略决定等待、跳过非关键依赖、终止或升级告警。</li></ol><p>必须区分两种动作：</p><ul><li>为了修复依赖本身而执行的恢复动作。</li><li>必须等待依赖健康后才能执行的上层动作。</li></ul><p>例如，代理不健康时，允许执行“切换代理节点”；但不应该执行依赖代理才能完成的 Cloudflare Tunnel 重启，然后期待它成功。</p><h2 id="_3-7-并发与依赖去重" tabindex="-1">3.7 并发与依赖去重 <a class="header-anchor" href="#_3-7-并发与依赖去重" aria-label="Permalink to “3.7 并发与依赖去重”">​</a></h2><p>同一资源可能被多个上层资源依赖。</p><p>例如：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Cloudflare Tunnel ──&gt; Proxy</span></span>
<span class="line"><span>Sunlogin ────────────&gt; Network</span></span>
<span class="line"><span>Other Service ───────&gt; Proxy</span></span></code></pre></div><p>如果多个恢复任务同时发现 Proxy 不健康，不能同时启动多个代理重启任务。</p><p>要求：</p><ul><li>每个资源有独立的恢复互斥锁。</li><li>同一资源同时最多有一个活动 RecoveryRun。</li><li>其他任务可以等待同一个恢复结果。</li><li>资源健康状态变化时，等待中的任务重新评估依赖。</li><li>恢复任务不能重复启动相同的高风险动作。</li><li>必须定义全局与资源级恢复预算。</li></ul><hr>`,71)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};